Definition optmb_init_post (ra sp gp tp s0 s1 a0 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (OPT : Z) (p n : word) (j0 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 p (wz 1) (wz 2) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(OPT, OPT + 24)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ rw_cells usegs m' OPT [C1 (b8 1); CB 7 j0; C8 p; C8 n].

Definition optmb_init_stmt : Prop :=
  forall (OPT MBP : Z) (p n : word) (j0 j1 j2 : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells usegs m OPT [C1 (b8 0); CB 7 j0; CB 8 j1; CB 8 j2] ->
  rw_cells usegs m MBP [C8 p; C8 n] ->
  (OPT + 24 <= MBP \/ MBP + 16 <= OPT) ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv usegs m ->
  evt usegs (optmb_init_post ra sp gp tp s0 s1 (wz OPT) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc OPT p n j0 m)
