(* [comment removed for export] *)
(* [comment removed for export] *)

Definition dbp_frame (fj : list byte) (s2 s1 s0 ra : word) : list cell := [CB 32 fj; C8 s2; C8 s1; C8 s0; C8 ra].

(* [comment removed for export] *)
Definition dbp_seg1_post (sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 a2 a3 a4 a5 a6 a7 t0 t1 t2 t3 t4 t5 t6 ra : word) (F : bvmap 5 word) (fc : bv 32)
    (OPT fb n ec lo : Z) (oj : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m' fj,
    ms' = MS (mkR (Z_to_bv 64 DBP_RET1) (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (Z_to_bv 64 ec) (Z_to_bv 64 OPT)
                  (Z_to_bv 64 fb) (Z_to_bv 64 n) a2 a3 a4 a5 a6 a7 a4 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_FB_PREPARE) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (OPT, OPT + 24)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp + -64)
    /\ rw_cells usegs m' (bv_unsigned sp + -64) (dbp_frame fj s2 s1 s0 ra)
    /\ rw_cells usegs m' OPT [CB 8 (b8 0 :: firstn 7 (skipn 1 oj)); CB 8 (b8 0 :: firstn 7 (skipn 9 oj)); CB 8 (skipn 16 oj)].
Scheme kc__3 := Elimination for Corelib.Init.Logic.ex Sort Prop.

Lemma dbp_seg1 : forall (OPT fb n ec lo : Z) (oj : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells usegs m OPT [CB 24 oj] ->
  stk usegs m lo (bv_unsigned sp) -> lo + 64 <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned sp <= OPT ->
  mem_inv usegs m ->
  evt usegs (dbp_seg1_post sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 (Z_to_bv 64 n) (Z_to_bv 64 ec) a4 a5 a6 a7 t0 t1 t2 t3 t4 t5 t6 ra F fc OPT fb n ec lo oj m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 OPT) (Z_to_bv 64 fb) (Z_to_bv 64 n) (Z_to_bv 64 ec) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
